{
  "name": "Signage Lab Platform v0",
  "description": "A mobile-first experimental digital signage management platform for provisioning media, playlists, templates, and devices.",
  "requestFramePermissions": [
    "camera",
    "microphone"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Media {
  mediaId: string;
  name: string;
  type: 'video' | 'image' | 'html';
  duration: number;
  tags: string[];
  url: string;
  previewUrl: string;
}

export interface Template {
  templateId: string;
  name: string;
  htmlSnippet: string;
  cssSnippet: string;
  jsSnippet: string;
}

export interface Playlist {
  playlistId: string;
  name: string;
  mediaIds: string[];
  templateId: string;
}

export interface Device {
  playerId: string;
  platform: string;
  model: string;
  capabilities: {
    videoCodec: string[];
    webgl: boolean;
    maxResolution: string;
  };
  lastSeen: string;
}

export interface PlayerConfig {
  playerId: string;
  configJSON: string;
  lastProvisioned: string;
}

export type ViewState = 'media' | 'playlist' | 'templates' | 'devices' | 'debug' | 'provision';

import { Media, Template, Playlist, Device, PlayerConfig } from '../types';

const KEYS = {
  MEDIA: 'signage_media',
  TEMPLATES: 'signage_templates',
  PLAYLISTS: 'signage_playlists',
  DEVICES: 'signage_devices',
  CONFIGS: 'signage_configs'
};

const DEFAULT_TEMPLATES: Template[] = [
  {
    templateId: 'temp-001',
    name: 'Standard Fullscreen',
    htmlSnippet: '<div id="player-container" class="fullscreen"></div>',
    cssSnippet: 'body { margin: 0; background: black; } .fullscreen { width: 100vw; height: 100vh; display: flex; align-items: center; justify-content: center; }',
    jsSnippet: 'console.log("Template Loaded: Fullscreen Initialized");'
  }
];

export const storage = {
  getMedia: (): Media[] => JSON.parse(localStorage.getItem(KEYS.MEDIA) || '[]'),
  saveMedia: (media: Media[]) => localStorage.setItem(KEYS.MEDIA, JSON.stringify(media)),

  getTemplates: (): Template[] => {
    const data = localStorage.getItem(KEYS.TEMPLATES);
    return data ? JSON.parse(data) : DEFAULT_TEMPLATES;
  },
  saveTemplates: (templates: Template[]) => localStorage.setItem(KEYS.TEMPLATES, JSON.stringify(templates)),

  getPlaylists: (): Playlist[] => JSON.parse(localStorage.getItem(KEYS.PLAYLISTS) || '[]'),
  savePlaylists: (playlists: Playlist[]) => localStorage.setItem(KEYS.PLAYLISTS, JSON.stringify(playlists)),

  getDevices: (): Device[] => JSON.parse(localStorage.getItem(KEYS.DEVICES) || '[]'),
  saveDevices: (devices: Device[]) => localStorage.setItem(KEYS.DEVICES, JSON.stringify(devices)),

  getConfigs: (): PlayerConfig[] => JSON.parse(localStorage.getItem(KEYS.CONFIGS) || '[]'),
  saveConfigs: (configs: PlayerConfig[]) => localStorage.setItem(KEYS.CONFIGS, JSON.stringify(configs)),
};

import React, { useState, useEffect } from 'react';
import { ViewState } from './types';
import MediaLibrary from './components/MediaLibrary';
import PlaylistBuilder from './components/PlaylistBuilder';
import TemplatesManager from './components/TemplatesManager';
import DeviceRegistry from './components/DeviceRegistry';
import DebugInspector from './components/DebugInspector';
import ProvisioningView from './components/ProvisioningView';
import { Layout, PlaySquare, FileCode, Monitor, Bug, Zap, Smartphone } from 'lucide-react';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<ViewState>('media');
  const [isMobile, setIsMobile] = useState(window.innerWidth < 768);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 768);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const renderContent = () => {
    switch (activeTab) {
      case 'media': return <MediaLibrary />;
      case 'playlist': return <PlaylistBuilder />;
      case 'templates': return <TemplatesManager />;
      case 'devices': return <DeviceRegistry />;
      case 'debug': return <DebugInspector />;
      case 'provision': return <ProvisioningView />;
      default: return <MediaLibrary />;
    }
  };

  const navItems = [
    { id: 'media', label: 'Media', icon: <Layout className="w-5 h-5" /> },
    { id: 'playlist', label: 'Playlists', icon: <PlaySquare className="w-5 h-5" /> },
    { id: 'templates', label: 'Templates', icon: <FileCode className="w-5 h-5" /> },
    { id: 'devices', label: 'Devices', icon: <Monitor className="w-5 h-5" /> },
    { id: 'debug', label: 'Debug', icon: <Bug className="w-5 h-5" /> },
    { id: 'provision', label: 'Provision', icon: <Zap className="w-5 h-5" /> },
  ];

  return (
    <div className="min-h-screen pb-20 md:pb-0 md:pl-64">
      {/* Desktop Sidebar */}
      <aside className="hidden md:flex flex-col w-64 fixed left-0 top-0 bottom-0 bg-white border-r border-slate-200 z-50">
        <div className="p-6 border-b border-slate-100">
          <h1 className="text-xl font-bold text-indigo-600 flex items-center gap-2">
            <Smartphone className="w-6 h-6" /> Signage Lab
          </h1>
          <p className="text-xs text-slate-400 mt-1 uppercase tracking-widest">Prototype v0</p>
        </div>
        <nav className="flex-1 p-4 space-y-2 overflow-y-auto">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id as ViewState)}
              className={`flex items-center gap-3 w-full px-4 py-3 rounded-xl transition-all ${
                activeTab === item.id 
                  ? 'bg-indigo-50 text-indigo-600 font-semibold' 
                  : 'text-slate-500 hover:bg-slate-50'
              }`}
            >
              {item.icon}
              {item.label}
            </button>
          ))}
        </nav>
      </aside>

      {/* Top Header Mobile */}
      <header className="md:hidden flex items-center justify-between p-4 bg-white border-b border-slate-100 sticky top-0 z-40">
        <h1 className="text-lg font-bold text-indigo-600 flex items-center gap-2">
           Signage Lab
        </h1>
        <div className="px-3 py-1 bg-indigo-50 text-indigo-600 rounded-full text-xs font-bold uppercase tracking-tighter">v0 Prototype</div>
      </header>

      {/* Main Content Area */}
      <main className="p-4 md:p-8 max-w-7xl mx-auto">
        {renderContent()}
      </main>

      {/* Bottom Navigation Mobile */}
      <nav className="md:hidden fixed bottom-0 left-0 right-0 bg-white border-t border-slate-100 flex justify-around p-2 z-50 shadow-lg">
        {navItems.map((item) => (
          <button
            key={item.id}
            onClick={() => setActiveTab(item.id as ViewState)}
            className={`flex flex-col items-center gap-1 flex-1 py-1 transition-colors ${
              activeTab === item.id ? 'text-indigo-600' : 'text-slate-400'
            }`}
          >
            {item.icon}
            <span className="text-[10px] font-medium">{item.label}</span>
          </button>
        ))}
      </nav>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { storage } from '../services/storage';
import { Media } from '../types';
import { Plus, Trash2, Image as ImageIcon, Video, ExternalLink, Tag } from 'lucide-react';

const MediaLibrary: React.FC = () => {
  const [mediaList, setMediaList] = useState<Media[]>([]);
  const [isAdding, setIsAdding] = useState(false);
  const [newMedia, setNewMedia] = useState<Partial<Media>>({
    type: 'image',
    duration: 10,
    tags: []
  });

  useEffect(() => {
    setMediaList(storage.getMedia());
  }, []);

  const handleAddMedia = () => {
    if (!newMedia.name || !newMedia.url) return;

    const mediaItem: Media = {
      mediaId: `media-${Date.now()}`,
      name: newMedia.name || 'Untitled',
      type: newMedia.type as 'video' | 'image' | 'html',
      duration: Number(newMedia.duration) || 10,
      tags: newMedia.tags || [],
      url: newMedia.url || '',
      previewUrl: newMedia.url || 'https://picsum.photos/400/300'
    };

    const updated = [...mediaList, mediaItem];
    setMediaList(updated);
    storage.saveMedia(updated);
    setIsAdding(false);
    setNewMedia({ type: 'image', duration: 10, tags: [] });
  };

  const removeMedia = (id: string) => {
    const updated = mediaList.filter(m => m.mediaId !== id);
    setMediaList(updated);
    storage.saveMedia(updated);
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Media Library</h2>
          <p className="text-slate-500 text-sm">Upload and manage signage assets</p>
        </div>
        <button 
          onClick={() => setIsAdding(true)}
          className="flex items-center gap-2 bg-indigo-600 text-white px-4 py-2 rounded-lg hover:bg-indigo-700 transition shadow-sm"
        >
          <Plus className="w-4 h-4" /> <span className="hidden sm:inline">Add Media</span>
        </button>
      </div>

      {isAdding && (
        <div className="bg-white p-6 rounded-2xl border border-indigo-100 shadow-xl animate-in fade-in slide-in-from-top-4 duration-300">
          <h3 className="text-lg font-bold mb-4 text-indigo-900">New Media Resource</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="space-y-2">
              <label className="text-xs font-bold uppercase text-slate-400">Resource Name</label>
              <input 
                className="w-full p-3 rounded-xl bg-slate-50 border border-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500" 
                placeholder="Marketing Video A" 
                onChange={e => setNewMedia({...newMedia, name: e.target.value})}
              />
            </div>
            <div className="space-y-2">
              <label className="text-xs font-bold uppercase text-slate-400">Resource URL (GCS/S3)</label>
              <input 
                className="w-full p-3 rounded-xl bg-slate-50 border border-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500" 
                placeholder="https://storage.googleapis.com/..." 
                onChange={e => setNewMedia({...newMedia, url: e.target.value})}
              />
            </div>
            <div className="space-y-2">
              <label className="text-xs font-bold uppercase text-slate-400">Type</label>
              <select 
                className="w-full p-3 rounded-xl bg-slate-50 border border-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500"
                value={newMedia.type}
                onChange={e => setNewMedia({...newMedia, type: e.target.value as any})}
              >
                <option value="image">Image</option>
                <option value="video">Video</option>
                <option value="html">HTML Wrapper</option>
              </select>
            </div>
            <div className="space-y-2">
              <label className="text-xs font-bold uppercase text-slate-400">Duration (seconds)</label>
              <input 
                type="number"
                className="w-full p-3 rounded-xl bg-slate-50 border border-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500" 
                value={newMedia.duration}
                onChange={e => setNewMedia({...newMedia, duration: Number(e.target.value)})}
              />
            </div>
          </div>
          <div className="flex gap-2 mt-6">
            <button 
              onClick={handleAddMedia}
              className="flex-1 bg-indigo-600 text-white font-bold py-3 rounded-xl shadow-md hover:bg-indigo-700"
            >
              Add to Library
            </button>
            <button 
              onClick={() => setIsAdding(false)}
              className="bg-slate-100 text-slate-600 px-6 py-3 rounded-xl font-bold"
            >
              Cancel
            </button>
          </div>
        </div>
      )}

      {mediaList.length === 0 ? (
        <div className="text-center py-20 bg-white rounded-2xl border-2 border-dashed border-slate-200">
          <Layout className="w-12 h-12 text-slate-300 mx-auto mb-4" />
          <h3 className="text-lg font-medium text-slate-400">Library is empty</h3>
          <p className="text-slate-400 text-sm">Add your first media asset to begin</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
          {mediaList.map(item => (
            <div key={item.mediaId} className="group bg-white rounded-2xl border border-slate-100 shadow-sm hover:shadow-md transition-all overflow-hidden relative">
              <div className="aspect-video bg-slate-100 relative overflow-hidden">
                <img src={item.previewUrl} alt={item.name} className="w-full h-full object-cover" />
                <div className="absolute top-2 left-2 flex gap-1">
                  <span className="bg-white/90 backdrop-blur px-2 py-1 rounded-md text-[10px] font-bold uppercase shadow-sm">
                    {item.type}
                  </span>
                  <span className="bg-indigo-600 text-white px-2 py-1 rounded-md text-[10px] font-bold shadow-sm">
                    {item.duration}s
                  </span>
                </div>
              </div>
              <div className="p-4">
                <div className="flex justify-between items-start">
                  <div>
                    <h4 className="font-bold text-slate-800 line-clamp-1">{item.name}</h4>
                    <p className="text-xs text-slate-400 font-mono mt-1">{item.mediaId}</p>
                  </div>
                  <button 
                    onClick={() => removeMedia(item.mediaId)}
                    className="text-slate-300 hover:text-red-500 transition"
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                </div>
                <div className="mt-3 flex gap-2 flex-wrap">
                  {item.tags.map(tag => (
                    <span key={tag} className="bg-slate-50 text-slate-500 text-[10px] px-2 py-0.5 rounded border border-slate-100 flex items-center gap-1">
                      <Tag className="w-2.5 h-2.5" /> {tag}
                    </span>
                  ))}
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default MediaLibrary;

import React, { useState, useEffect } from 'react';
import { storage } from '../services/storage';
import { Media, Playlist, Template } from '../types';
import { Plus, List, Save, ChevronRight, LayoutTemplate } from 'lucide-react';

const PlaylistBuilder: React.FC = () => {
  const [playlists, setPlaylists] = useState<Playlist[]>([]);
  const [mediaItems, setMediaItems] = useState<Media[]>([]);
  const [templates, setTemplates] = useState<Template[]>([]);
  const [isCreating, setIsCreating] = useState(false);

  const [newPlaylist, setNewPlaylist] = useState({
    name: '',
    selectedMedia: [] as string[],
    templateId: ''
  });

  useEffect(() => {
    setPlaylists(storage.getPlaylists());
    setMediaItems(storage.getMedia());
    setTemplates(storage.getTemplates());
  }, []);

  const handleCreate = () => {
    if (!newPlaylist.name || newPlaylist.selectedMedia.length === 0 || !newPlaylist.templateId) return;

    const playlist: Playlist = {
      playlistId: `playlist-${Date.now()}`,
      name: newPlaylist.name,
      mediaIds: newPlaylist.selectedMedia,
      templateId: newPlaylist.templateId
    };

    const updated = [...playlists, playlist];
    setPlaylists(updated);
    storage.savePlaylists(updated);
    setIsCreating(false);
    setNewPlaylist({ name: '', selectedMedia: [], templateId: '' });
  };

  const toggleMediaSelection = (id: string) => {
    setNewPlaylist(prev => ({
      ...prev,
      selectedMedia: prev.selectedMedia.includes(id) 
        ? prev.selectedMedia.filter(m => m !== id)
        : [...prev.selectedMedia, id]
    }));
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Playlist Builder</h2>
          <p className="text-slate-500 text-sm">Sequence assets for playback</p>
        </div>
        <button 
          onClick={() => setIsCreating(true)}
          className="flex items-center gap-2 bg-indigo-600 text-white px-4 py-2 rounded-lg hover:bg-indigo-700 transition"
        >
          <Plus className="w-4 h-4" /> <span className="hidden sm:inline">New Playlist</span>
        </button>
      </div>

      {isCreating && (
        <div className="bg-white p-6 rounded-2xl border border-indigo-100 shadow-xl space-y-6">
          <div className="space-y-2">
            <label className="text-xs font-bold uppercase text-slate-400">Playlist Name</label>
            <input 
              className="w-full p-3 rounded-xl bg-slate-50 border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none" 
              placeholder="e.g. Morning Retail Loop" 
              value={newPlaylist.name}
              onChange={e => setNewPlaylist({...newPlaylist, name: e.target.value})}
            />
          </div>

          <div className="space-y-2">
            <label className="text-xs font-bold uppercase text-slate-400">Step 1: Assign Template</label>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
              {templates.map(t => (
                <button
                  key={t.templateId}
                  onClick={() => setNewPlaylist({...newPlaylist, templateId: t.templateId})}
                  className={`p-3 rounded-xl text-left flex items-center gap-3 transition-all border ${
                    newPlaylist.templateId === t.templateId 
                      ? 'bg-indigo-50 border-indigo-500 text-indigo-700' 
                      : 'bg-slate-50 border-slate-200'
                  }`}
                >
                  <LayoutTemplate className="w-5 h-5" />
                  <span className="font-semibold text-sm">{t.name}</span>
                </button>
              ))}
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-xs font-bold uppercase text-slate-400">Step 2: Select Media (Drag/Drop Simulated)</label>
            <div className="max-h-60 overflow-y-auto grid grid-cols-1 gap-2 p-2 bg-slate-50 rounded-xl">
              {mediaItems.length === 0 ? <p className="text-center py-8 text-slate-400 italic text-sm">No media available. Upload some first.</p> : null}
              {mediaItems.map(m => (
                <button
                  key={m.mediaId}
                  onClick={() => toggleMediaSelection(m.mediaId)}
                  className={`p-3 rounded-lg text-left flex items-center justify-between transition-all border ${
                    newPlaylist.selectedMedia.includes(m.mediaId) 
                      ? 'bg-white border-indigo-300 shadow-sm' 
                      : 'bg-transparent border-transparent opacity-60'
                  }`}
                >
                  <div className="flex items-center gap-3">
                    <img src={m.previewUrl} className="w-10 h-10 rounded object-cover" />
                    <div>
                      <span className="font-bold text-sm block">{m.name}</span>
                      <span className="text-[10px] text-slate-400">{m.type} • {m.duration}s</span>
                    </div>
                  </div>
                  <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center ${
                    newPlaylist.selectedMedia.includes(m.mediaId) ? 'bg-indigo-600 border-indigo-600' : 'border-slate-300'
                  }`}>
                    {newPlaylist.selectedMedia.includes(m.mediaId) && <div className="w-2 h-2 bg-white rounded-full" />}
                  </div>
                </button>
              ))}
            </div>
          </div>

          <div className="flex gap-2 pt-4">
            <button 
              onClick={handleCreate}
              className="flex-1 bg-indigo-600 text-white font-bold py-3 rounded-xl hover:bg-indigo-700 shadow-lg shadow-indigo-100"
            >
              Save Playlist
            </button>
            <button 
              onClick={() => setIsCreating(false)}
              className="bg-slate-100 text-slate-600 px-6 py-3 rounded-xl font-bold"
            >
              Cancel
            </button>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 gap-4">
        {playlists.map(pl => (
          <div key={pl.playlistId} className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm flex items-center justify-between group hover:border-indigo-200 transition-colors">
            <div className="flex items-center gap-4">
              <div className="w-12 h-12 bg-indigo-50 rounded-xl flex items-center justify-center text-indigo-600">
                <List className="w-6 h-6" />
              </div>
              <div>
                <h3 className="font-bold text-slate-800">{pl.name}</h3>
                <div className="flex items-center gap-3 text-xs text-slate-400 mt-1">
                  <span>{pl.mediaIds.length} Items</span>
                  <span className="w-1 h-1 bg-slate-300 rounded-full" />
                  <span className="flex items-center gap-1"><LayoutTemplate className="w-3 h-3" /> {templates.find(t => t.templateId === pl.templateId)?.name || 'Missing Template'}</span>
                </div>
              </div>
            </div>
            <button className="p-2 text-slate-300 hover:text-indigo-600 group-hover:bg-indigo-50 rounded-lg transition">
              <ChevronRight className="w-5 h-5" />
            </button>
          </div>
        ))}
        {playlists.length === 0 && !isCreating && (
          <div className="text-center py-20 bg-white rounded-2xl border-2 border-dashed border-slate-200">
            <h3 className="text-lg font-medium text-slate-400 italic">No playlists created yet</h3>
          </div>
        )}
      </div>
    </div>
  );
};

export default PlaylistBuilder;

import React, { useState, useEffect } from 'react';
import { storage } from '../services/storage';
import { Template } from '../types';
import { FileCode, Code, Palette, Play, Save, Plus } from 'lucide-react';

const TemplatesManager: React.FC = () => {
  const [templates, setTemplates] = useState<Template[]>([]);
  const [editingTemplate, setEditingTemplate] = useState<Template | null>(null);

  useEffect(() => {
    setTemplates(storage.getTemplates());
  }, []);

  const handleSave = () => {
    if (!editingTemplate) return;
    const updated = templates.map(t => t.templateId === editingTemplate.templateId ? editingTemplate : t);
    if (!templates.find(t => t.templateId === editingTemplate.templateId)) {
        updated.push(editingTemplate);
    }
    setTemplates(updated);
    storage.saveTemplates(updated);
    setEditingTemplate(null);
  };

  const createNew = () => {
    setEditingTemplate({
      templateId: `temp-${Date.now()}`,
      name: 'New Custom Template',
      htmlSnippet: '<div class="content"></div>',
      cssSnippet: '.content { color: white; }',
      jsSnippet: 'console.log("Custom template active");'
    });
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">HTML Templates</h2>
          <p className="text-slate-500 text-sm">Design layouts with code snippets</p>
        </div>
        <button 
          onClick={createNew}
          className="flex items-center gap-2 bg-indigo-600 text-white px-4 py-2 rounded-lg"
        >
          <Plus className="w-4 h-4" /> <span>Add Template</span>
        </button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-1 space-y-3">
          {templates.map(t => (
            <button
              key={t.templateId}
              onClick={() => setEditingTemplate(t)}
              className={`w-full p-4 rounded-2xl border text-left transition-all ${
                editingTemplate?.templateId === t.templateId 
                  ? 'border-indigo-600 bg-white shadow-md' 
                  : 'border-slate-100 bg-slate-50 hover:border-slate-300'
              }`}
            >
              <div className="flex items-center gap-3">
                <div className="p-2 bg-indigo-50 text-indigo-600 rounded-lg">
                  <FileCode className="w-5 h-5" />
                </div>
                <div>
                  <h4 className="font-bold text-slate-800">{t.name}</h4>
                  <p className="text-[10px] text-slate-400 font-mono mt-0.5">{t.templateId}</p>
                </div>
              </div>
            </button>
          ))}
        </div>

        <div className="lg:col-span-2">
          {editingTemplate ? (
