import React, { useState, useEffect } from 'react';
import { storage } from '../services/storage';
import { Device, Playlist, Media, Template, PlayerConfig } from '../types';
import { Zap, Copy, Download, RefreshCw, CheckCircle } from 'lucide-react';

const ProvisioningView: React.FC = () => {
  const [devices, setDevices] = useState<Device[]>([]);
  const [playlists, setPlaylists] = useState<Playlist[]>([]);
  const [selectedDeviceId, setSelectedDeviceId] = useState('');
  const [selectedPlaylistId, setSelectedPlaylistId] = useState('');
  const [generatedConfig, setGeneratedConfig] = useState<any>(null);
  const [copySuccess, setCopySuccess] = useState(false);

  useEffect(() => {
    setDevices(storage.getDevices());
    setPlaylists(storage.getPlaylists());
  }, []);

  const handleGenerate = () => {
    const device = devices.find(d => d.playerId === selectedDeviceId);
    const playlist = playlists.find(p => p.playlistId === selectedPlaylistId);

    if (!device || !playlist) return;

    const mediaItems = storage.getMedia();
    const templates = storage.getTemplates();
    const template = templates.find(t => t.templateId === playlist.templateId);

    const config = {
      playerId: device.playerId,
      device: {
        platform: device.platform,
        model: device.model,
        capabilities: device.capabilities
      },
      playlist: {
        id: playlist.playlistId,
        name: playlist.name,
        items: playlist.mediaIds.map(mid => {
          const m = mediaItems.find(mi => mi.mediaId === mid);
          return {
            mediaId: m?.mediaId,
            type: m?.type,
            url: m?.url,
            duration: m?.duration
          };
        }),
        templateId: playlist.templateId
      },
      template: template ? {
        id: template.templateId,
        name: template.name,
        htmlSnippet: template.htmlSnippet,
        cssSnippet: template.cssSnippet,
        jsSnippet: template.jsSnippet
      } : null,
      debug: {
        enabled: true,
        wsEndpoint: "wss://my-signage-debug-endpoint.example.com"
      },
      lastProvisioned: new Date().toISOString()
    };

    setGeneratedConfig(config);

    // Persist config
    const existing = storage.getConfigs();
    const updated = [
      ...existing.filter(c => c.playerId !== device.playerId),
      {
        playerId: device.playerId,
        configJSON: JSON.stringify(config),
        lastProvisioned: config.lastProvisioned
      }
    ];
    storage.saveConfigs(updated);
  };

  const copyToClipboard = () => {
    if (!generatedConfig) return;
    navigator.clipboard.writeText(JSON.stringify(generatedConfig, null, 2));
    setCopySuccess(true);
    setTimeout(() => setCopySuccess(false), 2000);
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Provisioning</h2>
          <p className="text-slate-500 text-sm">Combine Device + Playlist into Player JSON</p>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="md:col-span-1 space-y-6">
          <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm space-y-4">
             <div className="space-y-2">
                <label className="text-xs font-bold uppercase text-slate-400">Target Device</label>
                <select 
                  className="w-full p-3 rounded-xl bg-slate-50 border border-slate-200 outline-none"
                  value={selectedDeviceId}
                  onChange={e => setSelectedDeviceId(e.target.value)}
                >
                  <option value="">Select a player...</option>
                  {devices.map(d => <option key={d.playerId} value={d.playerId}>{d.playerId} ({d.platform})</option>)}
                </select>
             </div>
             <div className="space-y-2">
                <label className="text-xs font-bold uppercase text-slate-400">Assign Playlist</label>
                <select 
                  className="w-full p-3 rounded-xl bg-slate-50 border border-slate-200 outline-none"
                  value={selectedPlaylistId}
                  onChange={e => setSelectedPlaylistId(e.target.value)}
                >
                  <option value="">Select a playlist...</option>
                  {playlists.map(p => <option key={p.playlistId} value={p.playlistId}>{p.name}</option>)}
                </select>
             </div>
             <button 
               onClick={handleGenerate}
               disabled={!selectedDeviceId || !selectedPlaylistId}
               className="w-full bg-indigo-600 text-white font-bold py-4 rounded-xl shadow-lg shadow-indigo-100 hover:bg-indigo-700 disabled:opacity-50 disabled:shadow-none transition-all flex items-center justify-center gap-2"
             >
                <Zap className="w-5 h-5 fill-current" /> Provision Player
             </button>
          </div>

          <div className="bg-indigo-50 p-6 rounded-2xl border border-indigo-100">
             <h4 className="text-indigo-900 font-bold mb-2 flex items-center gap-2">
                <RefreshCw className="w-4 h-4" /> Live Sync
             </h4>
             <p className="text-indigo-600/70 text-xs leading-relaxed">
                Once provisioned, the configuration is stored in the <strong>PlayerConfigs</strong> table. Your JS player should poll <code>/api/configs/{selectedDeviceId || 'playerId'}</code> to receive updates.
             </p>
          </div>
        </div>

        <div className="md:col-span-2">
           <div className="bg-slate-900 rounded-3xl overflow-hidden border border-slate-800 shadow-2xl flex flex-col h-[600px]">
              <div className="p-4 bg-slate-800 border-b border-slate-700 flex justify-between items-center">
                 <div className="flex gap-1.5">
                    <div className="w-2.5 h-2.5 rounded-full bg-red-500" />
                    <div className="w-2.5 h-2.5 rounded-full bg-yellow-500" />
                    <div className="w-2.5 h-2.5 rounded-full bg-green-500" />
                 </div>
                 <div className="text-[10px] font-mono text-slate-400 uppercase tracking-widest">player-config.json</div>
                 <div className="flex gap-2">
                    <button 
                      onClick={copyToClipboard}
                      className={`p-1.5 rounded-lg transition ${copySuccess ? 'bg-green-600 text-white' : 'text-slate-400 hover:bg-slate-700'}`}
                    >
                      {copySuccess ? <CheckCircle className="w-4 h-4" /> : <Copy className="w-4 h-4" />}
                    </button>
                    <button className="p-1.5 text-slate-400 hover:bg-slate-700 rounded-lg">
                      <Download className="w-4 h-4" />
                    </button>
                 </div>
              </div>
              <div className="flex-1 overflow-auto p-6 font-mono text-sm leading-relaxed text-indigo-300">
                 {generatedConfig ? (
                   <pre className="whitespace-pre-wrap">{JSON.stringify(generatedConfig, null, 2)}</pre>
                 ) : (
                   <div className="h-full flex flex-col items-center justify-center text-slate-600 opacity-30 text-center space-y-4">
                      <Zap className="w-16 h-16" />
                      <p className="text-lg">Select a device and playlist to generate configuration</p>
                   </div>
                 )}
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

export default ProvisioningView;

import React, { useState, useEffect } from 'react';
import { storage } from '../services/storage';
import { Media } from '../types';
// Fixed: Added 'Layout' to the imports from 'lucide-react'
import { Plus, Trash2, Image as ImageIcon, Video, ExternalLink, Tag, Layout } from 'lucide-react';

const MediaLibrary: React.FC = () => {
  const [mediaList, setMediaList] = useState<Media[]>([]);
  const [isAdding, setIsAdding] = useState(false);
  const [newMedia, setNewMedia] = useState<Partial<Media>>({
    type: 'image',
    duration: 10,
    tags: []
  });

  useEffect(() => {
    setMediaList(storage.getMedia());
  }, []);

  const handleAddMedia = () => {
    if (!newMedia.name || !newMedia.url) return;

    const mediaItem: Media = {
      mediaId: `media-${Date.now()}`,
      name: newMedia.name || 'Untitled',
      type: newMedia.type as 'video' | 'image' | 'html',
      duration: Number(newMedia.duration) || 10,
      tags: newMedia.tags || [],
      url: newMedia.url || '',
      previewUrl: newMedia.url || 'https://picsum.photos/400/300'
    };

    const updated = [...mediaList, mediaItem];
    setMediaList(updated);
    storage.saveMedia(updated);
    setIsAdding(false);
    setNewMedia({ type: 'image', duration: 10, tags: [] });
  };

  const removeMedia = (id: string) => {
    const updated = mediaList.filter(m => m.mediaId !== id);
    setMediaList(updated);
    storage.saveMedia(updated);
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Media Library</h2>
          <p className="text-slate-500 text-sm">Upload and manage signage assets</p>
        </div>
        <button 
          onClick={() => setIsAdding(true)}
          className="flex items-center gap-2 bg-indigo-600 text-white px-4 py-2 rounded-lg hover:bg-indigo-700 transition shadow-sm"
        >
          <Plus className="w-4 h-4" /> <span className="hidden sm:inline">Add Media</span>
        </button>
      </div>

      {isAdding && (
        <div className="bg-white p-6 rounded-2xl border border-indigo-100 shadow-xl animate-in fade-in slide-in-from-top-4 duration-300">
          <h3 className="text-lg font-bold mb-4 text-indigo-900">New Media Resource</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="space-y-2">
              <label className="text-xs font-bold uppercase text-slate-400">Resource Name</label>
              <input 
                className="w-full p-3 rounded-xl bg-slate-50 border border-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500" 
                placeholder="Marketing Video A" 
                onChange={e => setNewMedia({...newMedia, name: e.target.value})}
              />
            </div>
            <div className="space-y-2">
              <label className="text-xs font-bold uppercase text-slate-400">Resource URL (GCS/S3)</label>
              <input 
                className="w-full p-3 rounded-xl bg-slate-50 border border-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500" 
                placeholder="https://storage.googleapis.com/..." 
                onChange={e => setNewMedia({...newMedia, url: e.target.value})}
              />
            </div>
            <div className="space-y-2">
              <label className="text-xs font-bold uppercase text-slate-400">Type</label>
              <select 
                className="w-full p-3 rounded-xl bg-slate-50 border border-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500"
                value={newMedia.type}
                onChange={e => setNewMedia({...newMedia, type: e.target.value as any})}
              >
                <option value="image">Image</option>
                <option value="video">Video</option>
                <option value="html">HTML Wrapper</option>
              </select>
            </div>
            <div className="space-y-2">
              <label className="text-xs font-bold uppercase text-slate-400">Duration (seconds)</label>
              <input 
                type="number"
                className="w-full p-3 rounded-xl bg-slate-50 border border-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500" 
                value={newMedia.duration}
                onChange={e => setNewMedia({...newMedia, duration: Number(e.target.value)})}
              />
            </div>
          </div>
          <div className="flex gap-2 mt-6">
            <button 
              onClick={handleAddMedia}
              className="flex-1 bg-indigo-600 text-white font-bold py-3 rounded-xl shadow-md hover:bg-indigo-700"
            >
              Add to Library
            </button>
            <button 
              onClick={() => setIsAdding(false)}
              className="bg-slate-100 text-slate-600 px-6 py-3 rounded-xl font-bold"
            >
              Cancel
            </button>
          </div>
        </div>
      )}

      {mediaList.length === 0 ? (
        <div className="text-center py-20 bg-white rounded-2xl border-2 border-dashed border-slate-200">
          <Layout className="w-12 h-12 text-slate-300 mx-auto mb-4" />
          <h3 className="text-lg font-medium text-slate-400">Library is empty</h3>
          <p className="text-slate-400 text-sm">Add your first media asset to begin</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
          {mediaList.map(item => (
            <div key={item.mediaId} className="group bg-white rounded-2xl border border-slate-100 shadow-sm hover:shadow-md transition-all overflow-hidden relative">
              <div className="aspect-video bg-slate-100 relative overflow-hidden">
                <img src={item.previewUrl} alt={item.name} className="w-full h-full object-cover" />
                <div className="absolute top-2 left-2 flex gap-1">
                  <span className="bg-white/90 backdrop-blur px-2 py-1 rounded-md text-[10px] font-bold uppercase shadow-sm">
                    {item.type}
                  </span>
                  <span className="bg-indigo-600 text-white px-2 py-1 rounded-md text-[10px] font-bold shadow-sm">
                    {item.duration}s
                  </span>
                </div>
              </div>
              <div className="p-4">
                <div className="flex justify-between items-start">
                  <div>
                    <h4 className="font-bold text-slate-800 line-clamp-1">{item.name}</h4>
                    <p className="text-xs text-slate-400 font-mono mt-1">{item.mediaId}</p>
                  </div>
                  <button 
                    onClick={() => removeMedia(item.mediaId)}
                    className="text-slate-300 hover:text-red-500 transition"
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                </div>
                <div className="mt-3 flex gap-2 flex-wrap">
                  {item.tags.map(tag => (
                    <span key={tag} className="bg-slate-50 text-slate-500 text-[10px] px-2 py-0.5 rounded border border-slate-100 flex items-center gap-1">
                      <Tag className="w-2.5 h-2.5" /> {tag}
                    </span>
                  ))}
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default MediaLibrary;

export interface Media {
  mediaId: string;
  name: string;
  type: 'video' | 'image' | 'html';
  duration: number;
  tags: string[];
  url: string;
  previewUrl: string;
}

export interface Template {
  templateId: string;
  name: string;
  htmlSnippet: string;
  cssSnippet: string;
  jsSnippet: string;
}

export interface Playlist {
  playlistId: string;
  name: string;
  mediaIds: string[];
  templateId: string;
}

export interface Device {
  playerId: string;
  platform: string;
  model: string;
  capabilities: {
    videoCodec: string[];
    webgl: boolean;
    maxResolution: string;
  };
  lastSeen: string;
}

export interface PlayerConfig {
  playerId: string;
  device: {
    platform: string;
    model: string;
    capabilities: any;
  };
  playlist: {
    id: string;
    name: string;
    items: any[];
    templateId: string;
  };
  template: Template | null;
  debug: {
    enabled: boolean;
    wsEndpoint: string;
  };
  lastProvisioned: string;
}

export interface TelemetryEvent {
  id: string;
  type: 'playerInit' | 'mediaStart' | 'mediaEnd' | 'playlistEnd' | 'error' | 'templateLoad' | 'debugMessage';
  playerId: string;
  timestamp: string;
  payload: any;
}

export type ViewState = 'media' | 'playlist' | 'templates' | 'devices' | 'debug' | 'provision' | 'player';

import { Media, Template, Playlist, Device, PlayerConfig, TelemetryEvent } from '../types';

const KEYS = {
  MEDIA: 'signage_media',
  TEMPLATES: 'signage_templates',
  PLAYLISTS: 'signage_playlists',
  DEVICES: 'signage_devices',
  CONFIGS: 'signage_configs',
  TELEMETRY: 'signage_telemetry'
};

const DEFAULT_TEMPLATES: Template[] = [
  {
    templateId: 'temp-001',
    name: 'Standard Fullscreen',
    htmlSnippet: '<div id="player-container" class="fullscreen">\n  <div class="media-wrap">\n    <img src="{{media.url}}" class="content-item" />\n  </div>\n  <div class="overlay">\n    <h1>{{playlist.name}}</h1>\n    <p>Player: {{playerId}}</p>\n  </div>\n</div>',
    cssSnippet: 'body { margin: 0; background: black; font-family: sans-serif; } \n.fullscreen { width: 100vw; height: 100vh; position: relative; overflow: hidden; }\n.content-item { width: 100%; height: 100%; object-fit: cover; }\n.overlay { position: absolute; bottom: 20px; left: 20px; color: white; text-shadow: 0 2px 4px rgba(0,0,0,0.5); }',
    jsSnippet: 'console.log("Template Loaded: Fullscreen Initialized");'
  }
];

export const storage = {
  getMedia: (): Media[] => JSON.parse(localStorage.getItem(KEYS.MEDIA) || '[]'),
  saveMedia: (media: Media[]) => localStorage.setItem(KEYS.MEDIA, JSON.stringify(media)),

  getTemplates: (): Template[] => {
    const data = localStorage.getItem(KEYS.TEMPLATES);
    return data ? JSON.parse(data) : DEFAULT_TEMPLATES;
  },
  saveTemplates: (templates: Template[]) => localStorage.setItem(KEYS.TEMPLATES, JSON.stringify(templates)),

  getPlaylists: (): Playlist[] => JSON.parse(localStorage.getItem(KEYS.PLAYLISTS) || '[]'),
  savePlaylists: (playlists: Playlist[]) => localStorage.setItem(KEYS.PLAYLISTS, JSON.stringify(playlists)),

  getDevices: (): Device[] => JSON.parse(localStorage.getItem(KEYS.DEVICES) || '[]'),
  saveDevices: (devices: Device[]) => localStorage.setItem(KEYS.DEVICES, JSON.stringify(devices)),

  getConfigs: (): PlayerConfig[] => JSON.parse(localStorage.getItem(KEYS.CONFIGS) || '[]'),
  saveConfigs: (configs: PlayerConfig[]) => localStorage.setItem(KEYS.CONFIGS, JSON.stringify(configs)),

  getTelemetry: (): TelemetryEvent[] => JSON.parse(localStorage.getItem(KEYS.TELEMETRY) || '[]'),
  addTelemetry: (event: TelemetryEvent) => {
    const logs = storage.getTelemetry();
    logs.unshift(event); // Newest first
    localStorage.setItem(KEYS.TELEMETRY, JSON.stringify(logs.slice(0, 100))); // Keep last 100
  },
  clearTelemetry: () => localStorage.removeItem(KEYS.TELEMETRY)
};

import React, { useState, useEffect, useRef } from 'react';
import { storage } from '../services/storage';
import { PlayerConfig, TelemetryEvent } from '../types';
import { Play, Square, Loader2, AlertCircle } from 'lucide-react';

const VirtualPlayer: React.FC = () => {
  const [config, setConfig] = useState<PlayerConfig | null>(null);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const timerRef = useRef<number | null>(null);

  useEffect(() => {
    // For demo purposes, we load the most recently provisioned config
    const configs = storage.getConfigs();
    if (configs.length > 0) {
      setConfig(configs[configs.length - 1]);
    }
  }, []);

  const logEvent = (type: TelemetryEvent['type'], payload: any = {}) => {
    if (!config) return;
    const event: TelemetryEvent = {
      id: `ev-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
      type,
      playerId: config.playerId,
      timestamp: new Date().toISOString(),
      payload
    };
    storage.addTelemetry(event);
  };

  const startPlayback = () => {
    if (!config || config.playlist.items.length === 0) return;
    setIsPlaying(true);
    logEvent('playerInit', { version: '2.0.0-signage-lab' });
    playCurrentItem();
  };

  const stopPlayback = () => {
    setIsPlaying(false);
    if (timerRef.current) window.clearTimeout(timerRef.current);
    setCurrentIndex(0);
  };

  const playCurrentItem = () => {
    if (!config) return;
    const item = config.playlist.items[currentIndex];
    logEvent('mediaStart', { mediaId: item.mediaId, index: currentIndex });

    const duration = (item.duration || 10) * 1000;

    timerRef.current = window.setTimeout(() => {
      logEvent('mediaEnd', { mediaId: item.mediaId, index: currentIndex });

      const nextIndex = (currentIndex + 1) % config.playlist.items.length;
      if (nextIndex === 0) logEvent('playlistEnd', { playlistId: config.playlist.id });

      setCurrentIndex(nextIndex);
    }, duration);
  };

  useEffect(() => {
    if (isPlaying) {
      playCurrentItem();
    }
    return () => {
      if (timerRef.current) window.clearTimeout(timerRef.current);
    };
  }, [currentIndex, isPlaying]);

  if (!config) {
    return (
      <div className="h-[70vh] flex flex-col items-center justify-center bg-slate-900 rounded-3xl text-slate-400 p-8 text-center border-4 border-slate-800">
        <AlertCircle className="w-16 h-16 mb-4 opacity-20" />
        <h3 className="text-xl font-bold text-white mb-2">No Player Provisioned</h3>
        <p className="max-w-xs">Go to the Provisioning tab to assign a playlist to a device first.</p>
      </div>
    );
  }

  const currentMedia = config.playlist.items[currentIndex];

  // Simple template binding simulator
  const renderTemplate = (snippet: string) => {
    let result = snippet;
    result = result.replace(/\{\{media\.url\}\}/g, currentMedia?.url || '');
    result = result.replace(/\{\{playlist\.name\}\}/g, config.playlist.name);
    result = result.replace(/\{\{playerId\}\}/g, config.playerId);
    result = result.replace(/\{\{timestamp\}\}/g, new Date().toLocaleTimeString());
    return result;
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Virtual Player Engine</h2>
          <p className="text-slate-500 text-sm">Testing device: <span className="font-mono text-indigo-600">{config.playerId}</span></p>
        </div>
        <div className="flex gap-2">
          {!isPlaying ? (
            <button 
              onClick={startPlayback}
              className="bg-green-600 text-white px-6 py-2 rounded-xl font-bold flex items-center gap-2 hover:bg-green-700 shadow-lg shadow-green-100"
            >
              <Play className="w-4 h-4 fill-current" /> Launch Runtime
            </button>
          ) : (
            <button 
              onClick={stopPlayback}
              className="bg-red-600 text-white px-6 py-2 rounded-xl font-bold flex items-center gap-2 hover:bg-red-700"
            >
              <Square className="w-4 h-4 fill-current" /> Kill Process
            </button>
          )}
        </div>
      </div>

      <div className="relative aspect-video bg-black rounded-3xl overflow-hidden border-8 border-slate-800 shadow-2xl group">
        {!isPlaying ? (
          <div className="absolute inset-0 flex items-center justify-center text-slate-700 flex-col gap-4">
            <Loader2 className="w-12 h-12 opacity-10 animate-spin" />
            <p className="font-mono text-xs uppercase tracking-widest opacity-40">Standby Mode</p>
          </div>
        ) : (
          <div className="absolute inset-0 w-full h-full">
            {/* Simulation of Dynamic Template Rendering */}
            <style dangerouslySetInnerHTML={{ __html: config.template?.cssSnippet || '' }} />
            <div 
              className="w-full h-full"
              dangerouslySetInnerHTML={{ __html: renderTemplate(config.template?.htmlSnippet || '') }} 
            />
            {/* Progress bar overlay */}
            <div className="absolute top-0 left-0 h-1 bg-indigo-500 transition-all duration-1000 ease-linear" style={{ width: '100%' }} />
          </div>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm">
           <h4 className="text-xs font-black uppercase text-slate-400 mb-4 tracking-tighter">Current Playback State</h4>
           <div className="space-y-3">
              <div className="flex justify-between text-sm">
                <span className="text-slate-500">Resource</span>
                <span className="font-bold text-slate-800">{currentMedia?.mediaId || 'None'}</span>
              </div>
              <div className="flex justify-between text-sm">
                <span className="text-slate-500">Asset Type</span>
                <span className="bg-indigo-50 text-indigo-600 px-2 py-0.5 rounded font-bold text-[10px] uppercase">{currentMedia?.type || '-'}</span>
              </div>
              <div className="flex justify-between text-sm">
                <span className="text-slate-500">Playlist Loop</span>
                <span className="text-slate-800">{currentIndex + 1} / {config.playlist.items.length}</span>
              </div>
           </div>
        </div>
        <div className="bg-slate-900 p-6 rounded-2xl border border-slate-800 shadow-sm text-indigo-300 font-mono text-[10px]">
           <h4 className="text-[10px] font-black uppercase text-slate-600 mb-4 tracking-tighter">Engine Hook Logs</h4>
           <div className="h-20 overflow-y-auto space-y-1">
              <div>[SYSTEM] Initializing asset loader...</div>
              {isPlaying && <div>[PLAYER] Playing item {currentIndex}...</div>}
              {isPlaying && <div>[ENGINE] Template bound for {config.playerId}</div>}
           </div>
        </div>
      </div>
    </div>
  );
};

export default VirtualPlayer;

