import React, { useState, useEffect } from 'react';
import { storage } from '../services/storage';
import { Device, Playlist, Media, Template, PlayerConfig } from '../types';
import { Zap, Copy, Download, RefreshCw, CheckCircle } from 'lucide-react';

const ProvisioningView: React.FC = () => {
  const [devices, setDevices] = useState<Device[]>([]);
  const [playlists, setPlaylists] = useState<Playlist[]>([]);
  const [selectedDeviceId, setSelectedDeviceId] = useState('');
  const [selectedPlaylistId, setSelectedPlaylistId] = useState('');
  const [generatedConfig, setGeneratedConfig] = useState<any>(null);
  const [copySuccess, setCopySuccess] = useState(false);

  useEffect(() => {
    setDevices(storage.getDevices());
    setPlaylists(storage.getPlaylists());
  }, []);

  const handleGenerate = () => {
    const device = devices.find(d => d.playerId === selectedDeviceId);
    const playlist = playlists.find(p => p.playlistId === selectedPlaylistId);

    if (!device || !playlist) return;

    const mediaItems = storage.getMedia();
    const templates = storage.getTemplates();
    const template = templates.find(t => t.templateId === playlist.templateId);

    // Fix: Ensure the template object uses 'templateId' instead of 'id' to match Template interface and explicitly type config as PlayerConfig
    const config: PlayerConfig = {
      playerId: device.playerId,
      device: {
        platform: device.platform,
        model: device.model,
        capabilities: device.capabilities
      },
      playlist: {
        id: playlist.playlistId,
        name: playlist.name,
        items: playlist.mediaIds.map(mid => {
          const m = mediaItems.find(mi => mi.mediaId === mid);
          return {
            mediaId: m?.mediaId,
            type: m?.type,
            url: m?.url,
            duration: m?.duration
          };
        }),
        templateId: playlist.templateId
      },
      template: template ? {
        templateId: template.templateId,
        name: template.name,
        htmlSnippet: template.htmlSnippet,
        cssSnippet: template.cssSnippet,
        jsSnippet: template.jsSnippet
      } : null,
      debug: {
        enabled: true,
        wsEndpoint: "wss://my-signage-debug-endpoint.example.com"
      },
      lastProvisioned: new Date().toISOString()
    };

    setGeneratedConfig(config);

    // Persist config
    const existing = storage.getConfigs();
    // Fix: Store the full config object which matches PlayerConfig interface to resolve type errors
    const updated: PlayerConfig[] = [
      ...existing.filter(c => c.playerId !== device.playerId),
      config
    ];
    storage.saveConfigs(updated);
  };

  const copyToClipboard = () => {
    if (!generatedConfig) return;
    navigator.clipboard.writeText(JSON.stringify(generatedConfig, null, 2));
    setCopySuccess(true);
    setTimeout(() => setCopySuccess(false), 2000);
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Provisioning</h2>
          <p className="text-slate-500 text-sm">Combine Device + Playlist into Player JSON</p>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="md:col-span-1 space-y-6">
          <div className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm space-y-4">
             <div className="space-y-2">
                <label className="text-xs font-bold uppercase text-slate-400">Target Device</label>
                <select 
                  className="w-full p-3 rounded-xl bg-slate-50 border border-slate-200 outline-none"
                  value={selectedDeviceId}
                  onChange={e => setSelectedDeviceId(e.target.value)}
                >
                  <option value="">Select a player...</option>
                  {devices.map(d => <option key={d.playerId} value={d.playerId}>{d.playerId} ({d.platform})</option>)}
                </select>
             </div>
             <div className="space-y-2">
                <label className="text-xs font-bold uppercase text-slate-400">Assign Playlist</label>
                <select 
                  className="w-full p-3 rounded-xl bg-slate-50 border border-slate-200 outline-none"
                  value={selectedPlaylistId}
                  onChange={e => setSelectedPlaylistId(e.target.value)}
                >
                  <option value="">Select a playlist...</option>
                  {playlists.map(p => <option key={p.playlistId} value={p.playlistId}>{p.name}</option>)}
                </select>
             </div>
             <button 
               onClick={handleGenerate}
               disabled={!selectedDeviceId || !selectedPlaylistId}
               className="w-full bg-indigo-600 text-white font-bold py-4 rounded-xl shadow-lg shadow-indigo-100 hover:bg-indigo-700 disabled:opacity-50 disabled:shadow-none transition-all flex items-center justify-center gap-2"
             >
                <Zap className="w-5 h-5 fill-current" /> Provision Player
             </button>
          </div>

          <div className="bg-indigo-50 p-6 rounded-2xl border border-indigo-100">
             <h4 className="text-indigo-900 font-bold mb-2 flex items-center gap-2">
                <RefreshCw className="w-4 h-4" /> Live Sync
             </h4>
             <p className="text-indigo-600/70 text-xs leading-relaxed">
                Once provisioned, the configuration is stored in the <strong>PlayerConfigs</strong> table. Your JS player should poll <code>/api/configs/{selectedDeviceId || 'playerId'}</code> to receive updates.
             </p>
          </div>
        </div>

        <div className="md:col-span-2">
           <div className="bg-slate-900 rounded-3xl overflow-hidden border border-slate-800 shadow-2xl flex flex-col h-[600px]">
              <div className="p-4 bg-slate-800 border-b border-slate-700 flex justify-between items-center">
                 <div className="flex gap-1.5">
                    <div className="w-2.5 h-2.5 rounded-full bg-red-500" />
                    <div className="w-2.5 h-2.5 rounded-full bg-yellow-500" />
                    <div className="w-2.5 h-2.5 rounded-full bg-green-500" />
                 </div>
                 <div className="text-[10px] font-mono text-slate-400 uppercase tracking-widest">player-config.json</div>
                 <div className="flex gap-2">
                    <button 
                      onClick={copyToClipboard}
                      className={`p-1.5 rounded-lg transition ${copySuccess ? 'bg-green-600 text-white' : 'text-slate-400 hover:bg-slate-700'}`}
                    >
                      {copySuccess ? <CheckCircle className="w-4 h-4" /> : <Copy className="w-4 h-4" />}
                    </button>
                    <button className="p-1.5 text-slate-400 hover:bg-slate-700 rounded-lg">
                      <Download className="w-4 h-4" />
                    </button>
                 </div>
              </div>
              <div className="flex-1 overflow-auto p-6 font-mono text-sm leading-relaxed text-indigo-300">
                 {generatedConfig ? (
                   <pre className="whitespace-pre-wrap">{JSON.stringify(generatedConfig, null, 2)}</pre>
                 ) : (
                   <div className="h-full flex flex-col items-center justify-center text-slate-600 opacity-30 text-center space-y-4">
                      <Zap className="w-16 h-16" />
                      <p className="text-lg">Select a device and playlist to generate configuration</p>
                   </div>
                 )}
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

