              </div>
              <div className="flex-1 min-w-0">
                <p className="text-xs font-bold text-slate-800 truncate">Alex Rivera</p>
                <p className="text-[9px] text-slate-400 font-bold uppercase tracking-wider">Admin</p>
              </div>
           </div>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 p-4 md:p-10 max-w-6xl mx-auto w-full">
        {renderContent()}
