      {/* Bottom Navigation Mobile */}
      <nav className="md:hidden fixed bottom-0 left-0 right-0 bg-white/80 backdrop-blur-lg border-t border-slate-100 flex justify-around p-3 z-50 shadow-[0_-4px_12px_rgba(0,0,0,0.03)] rounded-t-3xl">
        {[navItems[0], navItems[1], navItems[2], navItems[3]].map((item) => (
          <button
            key={item.id}
