                 <h2 className="text-xl font-black text-slate-800 tracking-tight">Platform Modules</h2>
                 <button onClick={() => setIsMenuOpen(false)} className="p-2 bg-slate-100 rounded-full">
                    <X className="w-6 h-6 text-slate-400" />
                 </button>
              </div>
              <div className="grid grid-cols-2 gap-4">
                 {navItems.map(item => (
                   <button
                    key={item.id}
                    onClick={() => handleTabChange(item.id as ViewState)}
