import React, { useState, useEffect } from 'react';
import { storage } from '../services/storage';
import { Media } from '../types';
import { 
  Plus, 
  Trash2, 
  Search, 
  Filter, 
  Monitor, 
  Smartphone, 
  Tag, 
  Layout, 
  X,
  Image as ImageIcon,
  Video as VideoIcon,
  Code
} from 'lucide-react';

const MediaLibrary: React.FC = () => {
  const [mediaList, setMediaList] = useState<Media[]>([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [filterType, setFilterType] = useState<string>('all');
  const [filterOrientation, setFilterOrientation] = useState<string>('all');
  const [isAdding, setIsAdding] = useState(false);

  const [newMedia, setNewMedia] = useState<Partial<Media>>({
    type: 'image',
    duration: 10,
    tags: [],
    orientation: 'landscape',
    resolution: '1920x1080'
  });

  useEffect(() => {
    setMediaList(storage.getMedia());
  }, []);

  const handleAddMedia = () => {
    if (!newMedia.name || !newMedia.url) return;

    const mediaItem: Media = {
      mediaId: `media-${Date.now()}`,
      name: newMedia.name || 'Untitled',
      type: newMedia.type as 'video' | 'image' | 'html',
      duration: Number(newMedia.duration) || 10,
      tags: newMedia.tags || [],
      url: newMedia.url || '',
      previewUrl: newMedia.url || 'https://picsum.photos/400/300',
      orientation: newMedia.orientation as 'landscape' | 'portrait',
      resolution: newMedia.resolution || '1920x1080'
    };

    const updated = [...mediaList, mediaItem];
    setMediaList(updated);
    storage.saveMedia(updated);
    setIsAdding(false);
    setNewMedia({ type: 'image', duration: 10, tags: [], orientation: 'landscape', resolution: '1920x1080' });
  };

  const removeMedia = (id: string) => {
    const updated = mediaList.filter(m => m.mediaId !== id);
    setMediaList(updated);
    storage.saveMedia(updated);
  };

  const filteredMedia = mediaList.filter(m => {
    const matchesSearch = m.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                         m.tags.some(t => t.toLowerCase().includes(searchQuery.toLowerCase()));
    const matchesType = filterType === 'all' || m.type === filterType;
    const matchesOrientation = filterOrientation === 'all' || m.orientation === filterOrientation;
    return matchesSearch && matchesType && matchesOrientation;
  });

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 px-2">
        <div>
          <h2 className="text-2xl font-black text-slate-800 tracking-tight">Media Library</h2>
          <p className="text-slate-400 text-xs font-medium uppercase tracking-widest mt-1">Management & Asset Filtering</p>
        </div>
        <button 
          onClick={() => setIsAdding(true)}
          className="flex items-center gap-2 bg-sky-500 text-white px-5 py-2.5 rounded-2xl hover:bg-sky-600 transition-all shadow-lg shadow-sky-100 font-bold text-sm"
        >
          <Plus className="w-4 h-4" /> Add Asset
        </button>
      </div>

      {/* Search and Filter Bar */}
      <div className="bg-white p-4 rounded-3xl border border-slate-100 shadow-sm space-y-4">
        <div className="relative">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
          <input 
            type="text"
            placeholder="Search by name or tags..."
            className="w-full pl-11 pr-4 py-3 bg-slate-50 border-none rounded-2xl text-sm focus:ring-2 focus:ring-sky-500 outline-none transition-all"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>
        <div className="flex flex-wrap gap-2">
          <div className="flex items-center gap-2 bg-slate-50 px-3 py-1.5 rounded-xl border border-slate-100">
            <Filter className="w-3 h-3 text-slate-400" />
            <select 
              className="bg-transparent text-xs font-bold text-slate-600 outline-none cursor-pointer"
              value={filterType}
              onChange={(e) => setFilterType(e.target.value)}
            >
              <option value="all">All Types</option>
              <option value="image">Images</option>
              <option value="video">Videos</option>
              <option value="html">HTML</option>
            </select>
          </div>
          <div className="flex items-center gap-2 bg-slate-50 px-3 py-1.5 rounded-xl border border-slate-100">
            <Layout className="w-3 h-3 text-slate-400" />
            <select 
              className="bg-transparent text-xs font-bold text-slate-600 outline-none cursor-pointer"
              value={filterOrientation}
              onChange={(e) => setFilterOrientation(e.target.value)}
            >
              <option value="all">All Orientations</option>
              <option value="landscape">Landscape</option>
              <option value="portrait">Portrait</option>
            </select>
          </div>
        </div>
      </div>

      {isAdding && (
        <div className="bg-white p-8 rounded-[2.5rem] border border-sky-100 shadow-2xl animate-in fade-in zoom-in-95 duration-300 relative">
          <button onClick={() => setIsAdding(false)} className="absolute top-6 right-6 p-2 bg-slate-50 rounded-full text-slate-400">
            <X className="w-5 h-5" />
          </button>
          <h3 className="text-xl font-black mb-6 text-slate-800">New Media Resource</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="space-y-2">
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest px-1">Resource Name</label>
              <input 
                className="w-full p-4 rounded-2xl bg-slate-50 border-none focus:ring-2 focus:ring-sky-500 outline-none transition-all" 
                placeholder="Marketing Video A" 
                onChange={e => setNewMedia({...newMedia, name: e.target.value})}
              />
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest px-1">Resource URL (GCS/S3)</label>
              <input 
                className="w-full p-4 rounded-2xl bg-slate-50 border-none focus:ring-2 focus:ring-sky-500 outline-none transition-all" 
                placeholder="https://storage.googleapis.com/..." 
                onChange={e => setNewMedia({...newMedia, url: e.target.value})}
              />
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest px-1">Asset Type</label>
              <select 
                className="w-full p-4 rounded-2xl bg-slate-50 border-none focus:ring-2 focus:ring-sky-500 outline-none transition-all cursor-pointer font-bold text-slate-600"
                value={newMedia.type}
                onChange={e => setNewMedia({...newMedia, type: e.target.value as any})}
              >
                <option value="image">Image</option>
                <option value="video">Video</option>
                <option value="html">HTML Wrapper</option>
              </select>
            </div>
            <div className="grid grid-cols-2 gap-4">
               <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest px-1">Orientation</label>
                  <select 
                    className="w-full p-4 rounded-2xl bg-slate-50 border-none focus:ring-2 focus:ring-sky-500 outline-none transition-all font-bold text-slate-600"
                    value={newMedia.orientation}
                    onChange={e => setNewMedia({...newMedia, orientation: e.target.value as any})}
                  >
                    <option value="landscape">Landscape</option>
                    <option value="portrait">Portrait</option>
                  </select>
               </div>
               <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest px-1">Resolution</label>
                  <input 
                    className="w-full p-4 rounded-2xl bg-slate-50 border-none focus:ring-2 focus:ring-sky-500 outline-none transition-all" 
                    placeholder="1920x1080"
                    value={newMedia.resolution}
                    onChange={e => setNewMedia({...newMedia, resolution: e.target.value})}
                  />
               </div>
            </div>
          </div>
          <div className="flex gap-3 mt-8">
            <button 
              onClick={handleAddMedia}
              className="flex-1 bg-sky-500 text-white font-black py-4 rounded-2xl shadow-xl shadow-sky-100 hover:bg-sky-600 active:scale-95 transition-all"
            >
              Add to Library
            </button>
            <button 
              onClick={() => setIsAdding(false)}
              className="px-8 bg-slate-50 text-slate-500 py-4 rounded-2xl font-bold hover:bg-slate-100"
            >
              Cancel
            </button>
          </div>
        </div>
      )}

      {filteredMedia.length === 0 ? (
        <div className="text-center py-24 bg-white rounded-[2.5rem] border-2 border-dashed border-slate-100">
          <div className="w-16 h-16 bg-slate-50 rounded-full flex items-center justify-center mx-auto mb-4">
             <Layout className="w-8 h-8 text-slate-200" />
          </div>
          <h3 className="text-lg font-bold text-slate-800">No assets found</h3>
          <p className="text-slate-400 text-sm max-w-xs mx-auto mt-1">Try adjusting your filters or search query to find the asset you're looking for.</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredMedia.map(item => (
            <div key={item.mediaId} className="group bg-white rounded-3xl border border-slate-100 shadow-sm hover:shadow-xl hover:border-sky-100 transition-all overflow-hidden relative flex flex-col">
              <div className="aspect-video bg-slate-50 relative overflow-hidden">
                <img src={item.previewUrl} alt={item.name} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-700" />
                <div className="absolute top-4 left-4 flex gap-2">
                  <div className="bg-white/90 backdrop-blur px-3 py-1.5 rounded-xl text-[9px] font-black uppercase tracking-widest shadow-sm flex items-center gap-1.5">
                    {item.type === 'image' && <ImageIcon className="w-3 h-3 text-sky-500" />}
                    {item.type === 'video' && <VideoIcon className="w-3 h-3 text-rose-500" />}
                    {item.type === 'html' && <Code className="w-3 h-3 text-emerald-500" />}
                    {item.type}
                  </div>
                </div>
                <div className="absolute bottom-4 left-4 flex gap-2">
                   <div className="bg-slate-900/40 backdrop-blur-md px-2.5 py-1 rounded-lg text-white text-[8px] font-black uppercase tracking-tighter">
                      {item.orientation}
                   </div>
                   <div className="bg-slate-900/40 backdrop-blur-md px-2.5 py-1 rounded-lg text-white text-[8px] font-black uppercase tracking-tighter">
                      {item.resolution}
                   </div>
                </div>
              </div>
              <div className="p-5 flex-1 flex flex-col">
                <div className="flex justify-between items-start mb-4">
                  <div>
                    <h4 className="font-bold text-slate-800 line-clamp-1 text-sm">{item.name}</h4>
                    <p className="text-[10px] text-slate-400 font-mono mt-0.5">{item.mediaId}</p>
                  </div>
                  <button 
                    onClick={() => removeMedia(item.mediaId)}
                    className="p-2 text-slate-300 hover:text-rose-500 hover:bg-rose-50 rounded-xl transition-all"
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                </div>
                <div className="mt-auto flex gap-2 flex-wrap">
                  {item.tags.map(tag => (
                    <span key={tag} className="bg-sky-50 text-sky-600 text-[9px] font-bold px-2.5 py-1 rounded-lg border border-sky-100 flex items-center gap-1.5">
                      <Tag className="w-2.5 h-2.5" /> {tag}
                    </span>
                  ))}
                  <span className="bg-slate-50 text-slate-500 text-[9px] font-bold px-2.5 py-1 rounded-lg border border-slate-100">
                    {item.duration}s
                  </span>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

