const MediaLibrary: React.FC = () => {
  const [mediaList, setMediaList] = useState<Media[]>([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [filterType, setFilterType] = useState<string>('all');
  const [filterOrientation, setFilterOrientation] = useState<string>('all');
  const [isAdding, setIsAdding] = useState(false);

  const [newMedia, setNewMedia] = useState<Partial<Media>>({
    type: 'image',
    duration: 10,
    tags: [],
    orientation: 'landscape',
    resolution: '1920x1080'
  });

  useEffect(() => {
    setMediaList(storage.getMedia());
  }, []);

  const handleAddMedia = () => {
    if (!newMedia.name || !newMedia.url) return;

    const mediaItem: Media = {
      mediaId: `media-${Date.now()}`,
      name: newMedia.name || 'Untitled',
      type: newMedia.type as 'video' | 'image' | 'html',
      duration: Number(newMedia.duration) || 10,
      tags: newMedia.tags || [],
      url: newMedia.url || '',
      previewUrl: newMedia.url || 'https://picsum.photos/400/300',
      orientation: newMedia.orientation as 'landscape' | 'portrait',
      resolution: newMedia.resolution || '1920x1080',
      createdAt: new Date().toISOString()
    };

    const updated = [...mediaList, mediaItem];
    setMediaList(updated);
    storage.saveMedia(updated);
    setIsAdding(false);
    setNewMedia({ type: 'image', duration: 10, tags: [], orientation: 'landscape', resolution: '1920x1080' });
  };

  const removeMedia = (id: string) => {
    if (confirm('Are you sure you want to delete this asset?')) {
      const updated = mediaList.filter(m => m.mediaId !== id);
      setMediaList(updated);
      storage.saveMedia(updated);
    }
  };

  const filteredMedia = mediaList.filter(m => {
    const matchesSearch = m.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
                         m.tags.some(t => t.toLowerCase().includes(searchQuery.toLowerCase()));
    const matchesType = filterType === 'all' || m.type === filterType;
    const matchesOrientation = filterOrientation === 'all' || m.orientation === filterOrientation;
    return matchesSearch && matchesType && matchesOrientation;
  });

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 px-2">
        <div>
          <h2 className="text-2xl font-black text-slate-800 tracking-tight">Media Library</h2>
          <p className="text-slate-400 text-xs font-medium uppercase tracking-widest mt-1">Management & Asset Filtering</p>
        </div>
        <button 
          onClick={() => setIsAdding(true)}
          className="flex items-center gap-2 bg-sky-500 text-white px-5 py-2.5 rounded-2xl hover:bg-sky-600 transition-all shadow-lg shadow-sky-100 font-bold text-sm"
        >
