import React, { useState, useEffect } from 'react';
import { storage } from '../services/storage';
import { Device } from '../types';
import { Monitor, Cpu, Globe, CheckCircle2, MoreVertical, Plus, Trash2 } from 'lucide-react';

const DeviceRegistry: React.FC = () => {
  const [devices, setDevices] = useState<Device[]>([]);
  const [isAdding, setIsAdding] = useState(false);

  const refreshDevices = () => {
    setDevices(storage.getDevices());
  };

  useEffect(() => {
    refreshDevices();
  }, []);

  const addTestDevice = () => {
    const newDevice: Device = {
      playerId: `player-${Math.floor(Math.random() * 1000).toString().padStart(3, '0')}`,
      platform: 'webos',
      model: 'LG 55XE3C',
      capabilities: {
        videoCodec: ['h264', 'hevc'],
        webgl: true,
        maxResolution: '4k'
      },
      lastSeen: new Date().toISOString(),
      status: 'online'
    };
    const updated = [...devices, newDevice];
    setDevices(updated);
    storage.saveDevices(updated);
    setIsAdding(false);
  };

  const removeDevice = (id: string) => {
    if (confirm(`Remove device ${id}? This will stop all deployments.`)) {
      const updated = devices.filter(d => d.playerId !== id);
      setDevices(updated);
      storage.saveDevices(updated);
    }
  };

  const getStatus = (lastSeenStr: string) => {
    const lastSeen = new Date(lastSeenStr).getTime();
    const diffMins = (new Date().getTime() - lastSeen) / 1000 / 60;

    if (diffMins < 5) return { label: 'Online', color: 'bg-green-500', bg: 'bg-green-50', text: 'text-green-600' };
    if (diffMins < 30) return { label: 'Attention', color: 'bg-amber-500', bg: 'bg-amber-50', text: 'text-amber-600' };
    return { label: 'Offline', color: 'bg-slate-400', bg: 'bg-slate-50', text: 'text-slate-500' };
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center px-2">
        <div>
          <h2 className="text-2xl font-black text-slate-800 tracking-tight">Device Registry</h2>
          <p className="text-slate-500 text-xs font-medium uppercase tracking-widest mt-1">Player Fleet Management</p>
        </div>
        <button 
          onClick={() => setIsAdding(true)}
          className="flex items-center gap-2 bg-sky-500 text-white px-5 py-2.5 rounded-2xl shadow-lg shadow-sky-100 font-bold text-sm"
        >
          <Plus className="w-4 h-4" /> <span>Add Device</span>
        </button>
      </div>

      {isAdding && (
         <div className="bg-sky-500 p-8 rounded-[2.5rem] text-white flex flex-col items-center text-center animate-in zoom-in-95 duration-200">
            <div className="w-16 h-16 bg-white/20 rounded-full flex items-center justify-center mb-6">
              <Monitor className="w-8 h-8 text-white" />
            </div>
            <h3 className="text-xl font-black mb-2 tracking-tight">Register New Engine</h3>
            <p className="text-sky-100 text-sm mb-8 max-w-xs font-medium">Provision a simulation player to test your playlists and templates in the engine.</p>
            <div className="flex gap-3">
              <button 
                onClick={addTestDevice}
                className="bg-white text-sky-600 font-black px-8 py-3 rounded-2xl shadow-xl shadow-sky-600/20 active:scale-95 transition-all"
              >
                Launch Mock Device
              </button>
              <button 
                onClick={() => setIsAdding(false)}
                className="bg-sky-600 text-white font-bold px-8 py-3 rounded-2xl"
              >
                Cancel
              </button>
            </div>
         </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {devices.map(device => {
          const status = getStatus(device.lastSeen);
          return (
            <div key={device.playerId} className="bg-white rounded-[2rem] border border-slate-100 shadow-sm overflow-hidden hover:shadow-xl hover:border-sky-100 transition-all flex flex-col">
               <div className="p-6 flex justify-between items-start">
                  <div className="flex gap-4">
                     <div className="w-12 h-12 bg-slate-50 rounded-2xl flex items-center justify-center text-slate-400">
                        <Monitor className="w-6 h-6" />
                     </div>
                     <div>
                        <h4 className="font-black text-slate-800 tracking-tight">{device.playerId}</h4>
                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-wider">{device.platform} • {device.model}</p>
                     </div>
                  </div>
                  <div className={`flex items-center gap-1.5 ${status.bg} ${status.text} px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-wider border border-white`}>
                    <span className={`w-1.5 h-1.5 ${status.color} rounded-full ${status.label === 'Online' ? 'animate-pulse' : ''}`} /> {status.label}
                  </div>
               </div>

               <div className="px-6 pb-6 space-y-4 flex-1">
                  <div className="bg-slate-50/50 p-4 rounded-2xl border border-slate-100/50">
                     <div className="flex items-center gap-1.5 text-[9px] text-slate-400 font-black uppercase mb-3 tracking-widest">
                        <Cpu className="w-3 h-3 text-sky-500" /> System Params
                     </div>
                     <div className="flex gap-1.5 flex-wrap">
                        {device.capabilities.videoCodec.map(c => (
                           <span key={c} className="text-[9px] font-black text-slate-500 bg-white px-2 py-0.5 rounded-lg border border-slate-100 uppercase tracking-tighter">{c}</span>
                        ))}
                        {device.capabilities.webgl && <span className="text-[9px] font-black text-slate-500 bg-white px-2 py-0.5 rounded-lg border border-slate-100 uppercase tracking-tighter">webgl</span>}
                        <span className="text-[9px] font-black text-slate-500 bg-white px-2 py-0.5 rounded-lg border border-slate-100 uppercase tracking-tighter">{device.capabilities.maxResolution}</span>
                     </div>
                  </div>

                  <div className="flex items-center justify-between text-[10px]">
                     <div className="flex items-center gap-1.5 text-slate-400 font-bold">
                        <Globe className="w-3 h-3" /> Last Active
                     </div>
                     <span className="font-bold text-slate-600 bg-slate-100 px-2 py-0.5 rounded-lg">
                        {new Date(device.lastSeen).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                     </span>
                  </div>
               </div>

               <div className="p-4 bg-slate-50 border-t border-slate-50 flex justify-between gap-2">
                  <button 
                    onClick={() => removeDevice(device.playerId)}
                    className="p-2.5 text-slate-300 hover:text-rose-500 hover:bg-rose-50 rounded-xl transition-all"
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                  <button className="flex-1 text-[10px] font-black uppercase tracking-widest text-sky-600 bg-white px-4 py-2.5 rounded-xl border border-sky-100 hover:bg-sky-50 transition-all shadow-sm">
                     Remote Inspect
                  </button>
               </div>
            </div>
          );
        })}
        {devices.length === 0 && !isAdding && (
          <div className="col-span-full py-24 bg-white rounded-[2.5rem] border-2 border-dashed border-slate-100 flex flex-col items-center">
             <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mb-6">
                <Monitor className="w-10 h-10 text-slate-200" />
             </div>
             <h3 className="text-xl font-black text-slate-800 tracking-tight">No Devices Configured</h3>
             <p className="text-slate-400 text-sm max-w-xs text-center mt-2 px-6">Launch a mock player to start testing your experimental signage playlists.</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default DeviceRegistry;

import React, { useState, useEffect } from 'react';
import { storage } from '../services/storage';
import { Media, Playlist, Template } from '../types';
import { Plus, List, Save, ChevronRight, LayoutTemplate } from 'lucide-react';

const PlaylistBuilder: React.FC = () => {
  const [playlists, setPlaylists] = useState<Playlist[]>([]);
  const [mediaItems, setMediaItems] = useState<Media[]>([]);
  const [templates, setTemplates] = useState<Template[]>([]);
  const [isCreating, setIsCreating] = useState(false);

  const [newPlaylist, setNewPlaylist] = useState({
    name: '',
    selectedMedia: [] as string[],
    templateId: ''
  });

  useEffect(() => {
    setPlaylists(storage.getPlaylists());
    setMediaItems(storage.getMedia());
    setTemplates(storage.getTemplates());
  }, []);

  const handleCreate = () => {
    if (!newPlaylist.name || newPlaylist.selectedMedia.length === 0 || !newPlaylist.templateId) return;

    // Added createdAt property to satisfy Playlist interface
    const playlist: Playlist = {
      playlistId: `playlist-${Date.now()}`,
      name: newPlaylist.name,
      mediaIds: newPlaylist.selectedMedia,
      templateId: newPlaylist.templateId,
      createdAt: new Date().toISOString()
    };

    const updated = [...playlists, playlist];
    setPlaylists(updated);
    storage.savePlaylists(updated);
    setIsCreating(false);
    setNewPlaylist({ name: '', selectedMedia: [], templateId: '' });
  };

  const toggleMediaSelection = (id: string) => {
    setNewPlaylist(prev => ({
      ...prev,
      selectedMedia: prev.selectedMedia.includes(id) 
        ? prev.selectedMedia.filter(m => m !== id)
        : [...prev.selectedMedia, id]
    }));
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Playlist Builder</h2>
          <p className="text-slate-500 text-sm">Sequence assets for playback</p>
        </div>
        <button 
          onClick={() => setIsCreating(true)}
          className="flex items-center gap-2 bg-indigo-600 text-white px-4 py-2 rounded-lg hover:bg-indigo-700 transition"
        >
          <Plus className="w-4 h-4" /> <span className="hidden sm:inline">New Playlist</span>
        </button>
      </div>

      {isCreating && (
        <div className="bg-white p-6 rounded-2xl border border-indigo-100 shadow-xl space-y-6">
          <div className="space-y-2">
            <label className="text-xs font-bold uppercase text-slate-400">Playlist Name</label>
            <input 
              className="w-full p-3 rounded-xl bg-slate-50 border border-slate-200 focus:ring-2 focus:ring-indigo-500 outline-none" 
              placeholder="e.g. Morning Retail Loop" 
              value={newPlaylist.name}
              onChange={e => setNewPlaylist({...newPlaylist, name: e.target.value})}
            />
          </div>

          <div className="space-y-2">
            <label className="text-xs font-bold uppercase text-slate-400">Step 1: Assign Template</label>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
              {templates.map(t => (
                <button
                  key={t.templateId}
                  onClick={() => setNewPlaylist({...newPlaylist, templateId: t.templateId})}
                  className={`p-3 rounded-xl text-left flex items-center gap-3 transition-all border ${
                    newPlaylist.templateId === t.templateId 
                      ? 'bg-indigo-50 border-indigo-500 text-indigo-700' 
                      : 'bg-slate-50 border-slate-200'
                  }`}
                >
                  <LayoutTemplate className="w-5 h-5" />
                  <span className="font-semibold text-sm">{t.name}</span>
                </button>
              ))}
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-xs font-bold uppercase text-slate-400">Step 2: Select Media (Drag/Drop Simulated)</label>
            <div className="max-h-60 overflow-y-auto grid grid-cols-1 gap-2 p-2 bg-slate-50 rounded-xl">
              {mediaItems.length === 0 ? <p className="text-center py-8 text-slate-400 italic text-sm">No media available. Upload some first.</p> : null}
              {mediaItems.map(m => (
                <button
                  key={m.mediaId}
                  onClick={() => toggleMediaSelection(m.mediaId)}
                  className={`p-3 rounded-lg text-left flex items-center justify-between transition-all border ${
                    newPlaylist.selectedMedia.includes(m.mediaId) 
                      ? 'bg-white border-indigo-300 shadow-sm' 
                      : 'bg-transparent border-transparent opacity-60'
                  }`}
                >
                  <div className="flex items-center gap-3">
                    <img src={m.previewUrl} className="w-10 h-10 rounded object-cover" />
                    <div>
                      <span className="font-bold text-sm block">{m.name}</span>
                      <span className="text-[10px] text-slate-400">{m.type} • {m.duration}s</span>
                    </div>
                  </div>
                  <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center ${
                    newPlaylist.selectedMedia.includes(m.mediaId) ? 'bg-indigo-600 border-indigo-600' : 'border-slate-300'
                  }`}>
                    {newPlaylist.selectedMedia.includes(m.mediaId) && <div className="w-2 h-2 bg-white rounded-full" />}
                  </div>
                </button>
              ))}
            </div>
          </div>

          <div className="flex gap-2 pt-4">
            <button 
              onClick={handleCreate}
              className="flex-1 bg-indigo-600 text-white font-bold py-3 rounded-xl hover:bg-indigo-700 shadow-lg shadow-indigo-100"
            >
              Save Playlist
            </button>
            <button 
              onClick={() => setIsCreating(false)}
              className="bg-slate-100 text-slate-600 px-6 py-3 rounded-xl font-bold"
            >
              Cancel
            </button>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 gap-4">
        {playlists.map(pl => (
          <div key={pl.playlistId} className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm flex items-center justify-between group hover:border-indigo-200 transition-colors">
            <div className="flex items-center gap-4">
              <div className="w-12 h-12 bg-indigo-50 rounded-xl flex items-center justify-center text-indigo-600">
                <List className="w-6 h-6" />
              </div>
              <div>
                <h3 className="font-bold text-slate-800">{pl.name}</h3>
                <div className="flex items-center gap-3 text-xs text-slate-400 mt-1">
                  <span>{pl.mediaIds.length} Items</span>
                  <span className="w-1 h-1 bg-slate-300 rounded-full" />
                  <span className="flex items-center gap-1"><LayoutTemplate className="w-3 h-3" /> {templates.find(t => t.templateId === pl.templateId)?.name || 'Missing Template'}</span>
                </div>
              </div>
            </div>
            <button className="p-2 text-slate-300 hover:text-indigo-600 group-hover:bg-indigo-50 rounded-lg transition">
              <ChevronRight className="w-5 h-5" />
            </button>
          </div>
        ))}
        {playlists.length === 0 && !isCreating && (
          <div className="text-center py-20 bg-white rounded-2xl border-2 border-dashed border-slate-200">
            <h3 className="text-lg font-medium text-slate-400 italic">No playlists created yet</h3>
          </div>
        )}
      </div>
    </div>
  );
};

export default PlaylistBuilder;

import React, { useEffect, useState } from 'react';
