import React, { useState, useEffect, useRef, useMemo } from 'react';
import { storage } from '../services/storage';
import { PlayerConfig, TelemetryEvent } from '../types';
import { Play, Square, Loader2, AlertCircle, Maximize2, Terminal } from 'lucide-react';

const VirtualPlayer: React.FC = () => {
  const [config, setConfig] = useState<PlayerConfig | null>(null);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const timerRef = useRef<number | null>(null);

  useEffect(() => {
    const configs = storage.getConfigs();
    if (configs.length > 0) {
      setConfig(configs[configs.length - 1]);
    }
  }, []);

  const logEvent = (type: TelemetryEvent['type'], payload: any = {}) => {
    if (!config) return;
    const event: TelemetryEvent = {
      id: `ev-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
      type,
      playerId: config.playerId,
      timestamp: new Date().toISOString(),
      payload
    };
    storage.addTelemetry(event);
  };

  const currentMedia = config?.playlist.items[currentIndex];

  // High-fidelity rendering with Iframe
  const iframeDoc = useMemo(() => {
    if (!config || !isPlaying) return '';

    // Simple template variable replacement
    let html = config.template?.htmlSnippet || '';
    html = html.replace(/\{\{media\.url\}\}/g, currentMedia?.url || '');
    html = html.replace(/\{\{playlist\.name\}\}/g, config.playlist.name);
    html = html.replace(/\{\{playerId\}\}/g, config.playerId);
    html = html.replace(/\{\{timestamp\}\}/g, new Date().toLocaleTimeString());

    return `
      <!DOCTYPE html>
      <html>
        <head>
          <style>
            ${config.template?.cssSnippet}
            body { margin: 0; padding: 0; overflow: hidden; background: #000; color: #fff; }
          </style>
        </head>
        <body>
          ${html}
          <script>
            try {
              ${config.template?.jsSnippet}
            } catch (e) {
              console.error("Template Script Error:", e);
            }
          </script>
        </body>
      </html>
    `;
  }, [config, isPlaying, currentIndex]);

  const startPlayback = () => {
    if (!config || config.playlist.items.length === 0) return;
    setIsPlaying(true);
    logEvent('playerInit', { version: '1.0.0-production-engine' });
    playItem(0);
  };

  const stopPlayback = () => {
    setIsPlaying(false);
    if (timerRef.current) window.clearTimeout(timerRef.current);
    setCurrentIndex(0);
    logEvent('debugMessage', { message: 'Playback stopped by user' });
  };

  const playItem = (index: number) => {
    if (!config) return;
    const item = config.playlist.items[index];
    setCurrentIndex(index);
    logEvent('mediaStart', { mediaId: item.mediaId, index });

    const duration = (item.duration || 10) * 1000;

    timerRef.current = window.setTimeout(() => {
      logEvent('mediaEnd', { mediaId: item.mediaId, index });
      const nextIndex = (index + 1) % config.playlist.items.length;
      if (nextIndex === 0) logEvent('playlistEnd', { playlistId: config.playlist.id });
      playItem(nextIndex);
    }, duration);
  };

  if (!config) {
    return (
