  const tools = [
    { name: 'Meta Video Inspector', url: 'https://example.com/inspector/video', status: 'Active' },
    { name: 'Playlist Generator V3', url: 'https://example.com/playlist-gen', status: 'Maintenance' },
    { name: 'Remote Debug CLI', url: 'https://example.com/cli', status: 'Active' }
  ];

  const refreshLogs = () => {
    setLogs(storage.getTelemetry());
  };

  useEffect(() => {
    refreshLogs();
    const interval = setInterval(refreshLogs, 2000);
    return () => clearInterval(interval);
  }, []);

  const clearLogs = () => {
