      id: `cmd-${Date.now()}`,
      type: 'debugMessage',
      playerId: 'SYSTEM-CONSOLE',
      timestamp: new Date().toISOString(),
      payload: { command: command.trim(), status: 'Executed' }
    };
    storage.addTelemetry(event);
    setCommand('');
    refreshLogs();
