      </div>

      <div className="grid grid-cols-1 xl:grid-cols-12 gap-6">
        {/* Terminal Section */}
        <div className="xl:col-span-7 space-y-4">
           <div className="bg-slate-950 rounded-[2.5rem] p-8 shadow-2xl border border-slate-900 flex flex-col h-[650px] relative overflow-hidden">
