                 <div className="flex items-center gap-2 text-[10px] font-bold text-emerald-500/60 uppercase">
                    <Activity className="w-3 h-3 animate-pulse" /> WebSocket: Stable
                 </div>
              </div>

              {/* Logs Stream */}
              <div className="flex-1 space-y-3 font-mono text-[11px] overflow-y-auto mb-6 pr-2 no-scrollbar">
                 {logs.length === 0 && (
                   <div className="h-full flex flex-col items-center justify-center text-slate-700 italic">
                      <Terminal className="w-12 h-12 mb-4 opacity-10" />
