import React, { useState, useEffect } from 'react';
import { storage } from '../services/storage';
import { Device } from '../types';
import { Monitor, Cpu, Globe, CheckCircle2, MoreVertical, Plus, Trash2, Search, ExternalLink } from 'lucide-react';

const DeviceRegistry: React.FC = () => {
  const [devices, setDevices] = useState<Device[]>([]);
  const [isAdding, setIsAdding] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');

  const refreshDevices = () => {
    setDevices(storage.getDevices());
  };

  useEffect(() => {
    refreshDevices();
  }, []);

  const addTestDevice = () => {
    const newDevice: Device = {
      playerId: `player-${Math.floor(Math.random() * 1000).toString().padStart(3, '0')}`,
      platform: 'webos',
      model: 'LG 55XE3C',
      capabilities: {
        videoCodec: ['h264', 'hevc'],
        webgl: true,
        maxResolution: '4k'
      },
      lastSeen: new Date().toISOString(),
      status: 'online'
    };
    const updated = [...devices, newDevice];
    setDevices(updated);
    storage.saveDevices(updated);
    setIsAdding(false);
  };

  const removeDevice = (id: string) => {
    if (confirm(`Remove device ${id}? This will terminate all active deployments.`)) {
      const updated = devices.filter(d => d.playerId !== id);
      setDevices(updated);
      storage.saveDevices(updated);
    }
  };

  const getStatus = (lastSeenStr: string) => {
    const lastSeen = new Date(lastSeenStr).getTime();
    const diffMins = (new Date().getTime() - lastSeen) / 1000 / 60;

    if (diffMins < 5) return { label: 'Online', color: 'bg-emerald-500', bg: 'bg-emerald-50', text: 'text-emerald-600' };
    if (diffMins < 30) return { label: 'Attention', color: 'bg-amber-500', bg: 'bg-amber-50', text: 'text-amber-600' };
    return { label: 'Offline', color: 'bg-slate-400', bg: 'bg-slate-50', text: 'text-slate-500' };
  };

  const filteredDevices = devices.filter(d => 
    d.playerId.toLowerCase().includes(searchQuery.toLowerCase()) ||
    d.platform.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 px-2">
        <div>
          <h2 className="text-2xl font-black text-slate-800 tracking-tight">Fleet Registry</h2>
          <p className="text-slate-400 text-xs font-medium uppercase tracking-widest mt-1">Player Hardware & Provisioning Status</p>
        </div>
        <button 
          onClick={() => setIsAdding(true)}
          className="flex items-center gap-2 bg-sky-500 text-white px-5 py-2.5 rounded-2xl shadow-lg shadow-sky-100 font-black text-sm hover:bg-sky-600 transition-all"
        >
          <Plus className="w-4 h-4" /> <span>Add Player</span>
        </button>
      </div>

      <div className="bg-white p-4 rounded-3xl border border-slate-100 shadow-sm">
        <div className="relative">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300" />
          <input 
            type="text"
            placeholder="Filter players by ID, OS, or Model..."
            className="w-full pl-11 pr-4 py-3 bg-slate-50 border-none rounded-2xl text-sm focus:ring-2 focus:ring-sky-500 outline-none transition-all"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>
      </div>

      {isAdding && (
         <div className="bg-slate-900 p-10 rounded-[3rem] text-white flex flex-col items-center text-center animate-in zoom-in-95 duration-300 relative overflow-hidden shadow-2xl">
            <div className="absolute top-0 left-0 w-full h-1 bg-sky-500" />
            <div className="w-20 h-20 bg-white/10 rounded-full flex items-center justify-center mb-6">
              <Monitor className="w-10 h-10 text-sky-400" />
            </div>
            <h3 className="text-2xl font-black mb-2 tracking-tight">Initialize Virtual Engine</h3>
            <p className="text-slate-400 text-sm mb-10 max-w-sm font-medium leading-relaxed">Spawn a simulation player instance to validate your experimental content pipelines and template behavior.</p>
            <div className="flex gap-4">
              <button 
                onClick={addTestDevice}
                className="bg-white text-slate-950 font-black px-10 py-4 rounded-2xl shadow-xl shadow-sky-500/10 active:scale-95 transition-all"
              >
                Provision Instance
              </button>
              <button 
                onClick={() => setIsAdding(false)}
                className="bg-slate-800 text-slate-400 font-bold px-10 py-4 rounded-2xl hover:text-white transition-colors"
              >
                Cancel
              </button>
            </div>
         </div>
      )}

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredDevices.map(device => {
          const status = getStatus(device.lastSeen);
          return (
            <div key={device.playerId} className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden hover:shadow-xl hover:border-sky-100 transition-all flex flex-col group">
               <div className="p-6 flex justify-between items-start">
                  <div className="flex gap-4">
                     <div className="w-14 h-14 bg-slate-50 rounded-[1.25rem] flex items-center justify-center text-slate-400 group-hover:bg-sky-50 group-hover:text-sky-500 transition-all">
                        <Monitor className="w-7 h-7" />
                     </div>
                     <div className="min-w-0">
                        <h4 className="font-black text-slate-800 tracking-tight truncate w-32">{device.playerId}</h4>
                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">{device.platform}</p>
                     </div>
                  </div>
                  <div className={`flex items-center gap-1.5 ${status.bg} ${status.text} px-3 py-1.5 rounded-xl text-[9px] font-black uppercase tracking-widest border border-white shadow-sm`}>
                    <span className={`w-1.5 h-1.5 ${status.color} rounded-full ${status.label === 'Online' ? 'animate-pulse' : ''}`} /> {status.label}
                  </div>
               </div>

               <div className="px-8 pb-8 space-y-5 flex-1">
                  <div className="bg-slate-50/50 p-5 rounded-3xl border border-slate-100/50">
                     <div className="flex items-center gap-2 text-[10px] text-slate-400 font-black uppercase mb-4 tracking-widest">
                        <Cpu className="w-3.5 h-3.5 text-sky-500" /> Capabilities
                     </div>
                     <div className="flex gap-2 flex-wrap">
                        {device.capabilities.videoCodec.map(c => (
                           <span key={c} className="text-[9px] font-black text-slate-500 bg-white px-2.5 py-1 rounded-lg border border-slate-100 uppercase tracking-tighter">{c}</span>
                        ))}
                        {device.capabilities.webgl && <span className="text-[9px] font-black text-slate-500 bg-white px-2.5 py-1 rounded-lg border border-slate-100 uppercase tracking-tighter">webgl</span>}
                        <span className="text-[9px] font-black text-slate-500 bg-white px-2.5 py-1 rounded-lg border border-slate-100 uppercase tracking-tighter">{device.capabilities.maxResolution}</span>
                     </div>
                  </div>

                  <div className="flex items-center justify-between">
                     <div className="flex items-center gap-2 text-[10px] text-slate-400 font-bold uppercase tracking-widest">
                        <Globe className="w-3.5 h-3.5 text-sky-400" /> Pulse
                     </div>
                     <span className="text-[10px] font-black text-slate-600 bg-slate-50 px-3 py-1 rounded-xl">
                        {new Date(device.lastSeen).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })}
                     </span>
                  </div>
               </div>

               <div className="p-4 bg-slate-50/50 border-t border-slate-50 flex justify-between gap-3 px-6">
                  <button 
                    onClick={() => removeDevice(device.playerId)}
                    className="p-3 text-slate-300 hover:text-rose-500 hover:bg-white rounded-2xl transition-all shadow-sm"
                  >
                    <Trash2 className="w-5 h-5" />
                  </button>
                  <button 
                    onClick={() => alert(`Remote inspection requested for ${device.playerId}`)}
                    className="flex-1 text-[10px] font-black uppercase tracking-[0.15em] text-sky-600 bg-white px-6 py-3 rounded-2xl border border-sky-100 hover:bg-sky-50 transition-all shadow-sm flex items-center justify-center gap-2"
                  >
                     <ExternalLink className="w-3.5 h-3.5" /> Inspect Player
                  </button>
               </div>
            </div>
          );
        })}
        {filteredDevices.length === 0 && (
          <div className="col-span-full py-32 bg-white rounded-[3rem] border-2 border-dashed border-slate-100 flex flex-col items-center">
             <div className="w-24 h-24 bg-slate-50 rounded-full flex items-center justify-center mb-8">
                <Monitor className="w-12 h-12 text-slate-200" />
             </div>
             <h3 className="text-xl font-black text-slate-800 tracking-tight">No Players Discovered</h3>
             <p className="text-slate-400 text-sm max-w-xs text-center mt-2 px-8 font-medium">Provision a simulation engine to start orchestrating your experimental signage playlists.</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default DeviceRegistry;

