    }
  }, []);

  const logEvent = (type: TelemetryEvent['type'], payload: any = {}) => {
    if (!config) return;
    const event: TelemetryEvent = {
      id: `ev-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
      type,
      playerId: config.playerId,
      timestamp: new Date().toISOString(),
      payload
    };
    storage.addTelemetry(event);
  };

  const currentMedia = config?.playlist.items[currentIndex];

  // High-fidelity rendering with Iframe
  const iframeDoc = useMemo(() => {
    if (!config || !isPlaying) return '';

    // Simple template variable replacement
    let html = config.template?.htmlSnippet || '';
    html = html.replace(/\{\{media\.url\}\}/g, currentMedia?.url || '');
    html = html.replace(/\{\{playlist\.name\}\}/g, config.playlist.name);
    html = html.replace(/\{\{playerId\}\}/g, config.playerId);
    html = html.replace(/\{\{timestamp\}\}/g, new Date().toLocaleTimeString());

    return `
      <!DOCTYPE html>
      <html>
        <head>
          <style>
            ${config.template?.cssSnippet}
            body { margin: 0; padding: 0; overflow: hidden; background: #000; color: #fff; }
          </style>
        </head>
        <body>
          ${html}
          <script>
            try {
              ${config.template?.jsSnippet}
            } catch (e) {
              console.error("Template Script Error:", e);
            }
          </script>
        </body>
      </html>
    `;
  }, [config, isPlaying, currentIndex]);

  const startPlayback = () => {
    if (!config || config.playlist.items.length === 0) return;
    setIsPlaying(true);
    logEvent('playerInit', { version: '1.0.0-production-engine' });
    playItem(0);
  };

  const stopPlayback = () => {
    setIsPlaying(false);
    if (timerRef.current) window.clearTimeout(timerRef.current);
    setCurrentIndex(0);
    logEvent('debugMessage', { message: 'Playback stopped by user' });
  };

  const playItem = (index: number) => {
    if (!config) return;
    const item = config.playlist.items[index];
    setCurrentIndex(index);
    logEvent('mediaStart', { mediaId: item.mediaId, index });

    const duration = (item.duration || 10) * 1000;

    timerRef.current = window.setTimeout(() => {
      logEvent('mediaEnd', { mediaId: item.mediaId, index });
      const nextIndex = (index + 1) % config.playlist.items.length;
      if (nextIndex === 0) logEvent('playlistEnd', { playlistId: config.playlist.id });
      playItem(nextIndex);
    }, duration);
  };

  if (!config) {
    return (
      <div className="h-[70vh] flex flex-col items-center justify-center bg-slate-900 rounded-[3rem] text-slate-400 p-8 text-center border border-slate-800 shadow-2xl">
        <div className="w-20 h-20 bg-slate-800 rounded-full flex items-center justify-center mb-6">
           <AlertCircle className="w-10 h-10 text-slate-600" />
        </div>
        <h3 className="text-xl font-black text-white mb-2 tracking-tight">Engine Not Provisioned</h3>
        <p className="max-w-xs text-sm text-slate-500 font-medium">Please configure a player deployment in the Provisioning view to activate this engine.</p>
        <button 
          className="mt-8 px-6 py-2.5 bg-sky-500 text-white font-bold rounded-2xl hover:bg-sky-600 transition-all shadow-lg shadow-sky-900/20"
          onClick={() => window.location.reload()} // Simplified navigation helper
        >
          Check Deployments
        </button>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4 px-2">
        <div>
          <h2 className="text-2xl font-black text-slate-800 tracking-tight flex items-center gap-2">
            Runtime Engine <span className="text-xs font-black uppercase px-2 py-0.5 bg-indigo-50 text-indigo-500 rounded-lg">v1.0</span>
          </h2>
          <p className="text-slate-400 text-xs font-medium uppercase tracking-widest mt-1">
            Active: <span className="text-slate-600 font-mono">{config.playerId}</span>
          </p>
        </div>
        <div className="flex gap-3">
          {!isPlaying ? (
            <button 
              onClick={startPlayback}
              className="bg-emerald-500 text-white px-8 py-3 rounded-2xl font-black shadow-xl shadow-emerald-100 hover:bg-emerald-600 transition-all flex items-center gap-2"
            >
              <Play className="w-4 h-4 fill-current" /> Boot System
            </button>
          ) : (
            <button 
              onClick={stopPlayback}
              className="bg-rose-500 text-white px-8 py-3 rounded-2xl font-black shadow-xl shadow-rose-100 hover:bg-rose-600 transition-all flex items-center gap-2"
            >
              <Square className="w-4 h-4 fill-current" /> Shutdown
            </button>
          )}
        </div>
      </div>

      {/* Screen Simulation */}
      <div className="relative aspect-video bg-black rounded-[2.5rem] overflow-hidden border-8 border-slate-900 shadow-2xl group">
        {!isPlaying ? (
          <div className="absolute inset-0 flex flex-col items-center justify-center bg-slate-950">
            <Loader2 className="w-12 h-12 text-slate-800 animate-spin mb-4" />
            <p className="text-[10px] font-black uppercase text-slate-700 tracking-[0.3em]">System Standby</p>
          </div>
        ) : (
          <iframe 
            srcDoc={iframeDoc}
            className="w-full h-full border-none pointer-events-none"
            title="Player Output"
            sandbox="allow-scripts"
          />
        )}

        {/* HUD Overlay */}
        {isPlaying && (
          <div className="absolute top-6 left-6 right-6 flex justify-between items-start opacity-0 group-hover:opacity-100 transition-opacity duration-300 pointer-events-none">
             <div className="bg-slate-900/80 backdrop-blur-xl p-3 rounded-2xl border border-white/10 text-white shadow-2xl">
                <div className="flex items-center gap-2 mb-1">
                   <div className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse" />
                   <span className="text-[10px] font-black uppercase tracking-widest">Streaming</span>
                </div>
                <h4 className="text-xs font-bold truncate max-w-[150px]">{currentMedia?.mediaId}</h4>
             </div>
             <button className="p-3 bg-white/10 backdrop-blur-xl rounded-2xl text-white border border-white/10">
                <Maximize2 className="w-4 h-4" />
             </button>
          </div>
        )}
      </div>

      {/* Engine Metrics */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm flex flex-col">
           <h4 className="text-[10px] font-black uppercase text-slate-400 mb-6 tracking-widest flex items-center gap-2">
              <Activity className="w-3.5 h-3.5 text-sky-500" /> Active Context
           </h4>
           <div className="space-y-4 flex-1">
              <div className="flex justify-between items-center pb-4 border-b border-slate-50">
                <span className="text-xs font-bold text-slate-400">Media Index</span>
                <span className="text-sm font-black text-slate-800">{currentIndex + 1} / {config.playlist.items.length}</span>
              </div>
              <div className="flex justify-between items-center pb-4 border-b border-slate-50">
                <span className="text-xs font-bold text-slate-400">Asset Type</span>
                <span className="text-[10px] font-black uppercase tracking-widest bg-slate-900 text-white px-2 py-0.5 rounded-md">{currentMedia?.type || 'IDLE'}</span>
              </div>
              <div className="flex justify-between items-center">
                <span className="text-xs font-bold text-slate-400">Network Latency</span>
                <span className="text-xs font-black text-emerald-500">12ms</span>
              </div>
           </div>
        </div>

        <div className="bg-slate-950 p-6 rounded-[2rem] border border-slate-900 shadow-xl flex flex-col">
           <h4 className="text-[10px] font-black uppercase text-slate-600 mb-6 tracking-widest flex items-center gap-2">
              <Terminal className="w-3.5 h-3.5 text-sky-500" /> Console Output
           </h4>
           <div className="flex-1 overflow-y-auto font-mono text-[10px] space-y-2 text-sky-100/60 no-scrollbar max-h-32">
              <div className="text-emerald-500/80">[SYSTEM] Boot sequence initialized...</div>
              {isPlaying ? (
                <>
                  <div className="text-white/40">[RENDER] Frame cycle starting @ 60fps</div>
                  <div className="text-sky-400">[PLAYER] Fetching content: {currentMedia?.mediaId}</div>
                  <div className="text-white/40">[STORAGE] Local cache hit for URL</div>
                </>
              ) : (
                <div className="text-white/20 italic">Awaiting boot command...</div>
              )}
           </div>
        </div>
      </div>
    </div>
  );
};

export default VirtualPlayer;
